package app;

import app.repositories.AuthorRepository;
import app.repositories.MemoryAuthorRepository;
import app.repositories.MemoryPostRepository;
import app.repositories.PostRepository;
import java.util.function.Function;

/** The in-memory repositories, for tests and for trying the services without a database. */
public class MemoryUnitOfWork implements UnitOfWork {
    private final AuthorRepository authors = new MemoryAuthorRepository();
    private final PostRepository posts = new MemoryPostRepository();

    @Override
    public AuthorRepository authors() {
        return authors;
    }

    @Override
    public PostRepository posts() {
        return posts;
    }

    /** Memory has no transactions: changes are kept as they are made. */
    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

