/** A document of the "posts" collection. Its indexes are for the tests: in the application's database they are not touched. */
@Document(collection = "posts")
@CompoundIndex(name = "ix_posts_author", def = "{'author': 1}")
public class Post {
    @Id
    private String id;

    private String title;

    @Field(targetType = FieldType.OBJECT_ID)
    private String author;

    @Field("published_at")
    private Instant publishedAt;

    private List<Post.Comment> comments;

    public String getId() {
