    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getAuthor() {
        return author;
    }

    public void setAuthor(String author) {
        this.author = author;
    }

    public Instant getPublishedAt() {
        return publishedAt;
    }

    public void setPublishedAt(Instant publishedAt) {
        this.publishedAt = publishedAt;
    }

    public List<Post.Comment> getComments() {
        return comments;
    }

    public void setComments(List<Post.Comment> comments) {
        this.comments = comments;
    }

    /** Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents. */
    public void identifyItems() {
        if (comments != null) {
            comments.forEach((item) -> {
                if (item.getId() == null) item.setId(new ObjectId().toHexString());
            });
