    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("title", "author", "published_at", "comments");

    private final MongoTemplate mongo;

    public MongoPostRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<Post> findById(String id) {
        Post found = mongo.findOne(Query.query(Criteria.where("id").is(id)), Post.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Post> list(int offset, int limit) {
        List<Post> items = mongo.find(new Query().with(Sort.by("id")).skip(offset).limit(limit), Post.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), Post.class), offset, limit);
    }

    @Override
    public List<Post> listByAuthor(String author) {
        return mongo.find(Query.query(Criteria.where("author").is(author)).with(Sort.by("id")), Post.class).stream().map(this::loaded).toList();
    }

    @Override
    public Post insert(Post entity) {
        entity.identifyItems();
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Post", error);
        }
        return loaded(entity);
    }

    @Override
    public Post update(Post entity) {
        entity.identifyItems();
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Post.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Post", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Post entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Post.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Post", error);
        }
    }

    @Override
    public Optional<Post> addComment(String id, Post.Comment comment) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        if (comment.getId() == null) comment.setId(new ObjectId().toHexString());
        Document change = new Document("$push", new Document("comments", Documents.of(mongo, comment)));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Post.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Post", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Post.class, document)));
    }

    @Override
    public Optional<Post> removeComment(String id, String commentId) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        if (!ObjectId.isValid(commentId)) return Optional.empty();
        Document change = new Document("$pull", new Document("comments", new Document("_id", new ObjectId(commentId))));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Post.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Post", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Post.class, document)));
    }

