/** Operations on authors. Repositories commit every write. */
public class AuthorService {
    private final UnitOfWork uow;

    public AuthorService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "authors" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Author current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("email");
            if (value == null) {
                if (creating || values.containsKey("email")) errors.add(new FieldError("email", "is required"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Author", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Author current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Author entity, Map<String, Object> values) {
        if (values.containsKey("email")) entity.setEmail((String) values.get("email"));
    }

    /** The Author with this key; NotFoundException when there is none. */
    private Author find(UnitOfWork uow, String id) {
        return uow.authors().findById(id).orElseThrow(() -> new NotFoundException("Author", id));
    }

    /** The Author as services return it. */
    private static AuthorRead read(Author entity) {
        return new AuthorRead(entity.getId(), entity.getEmail());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(AuthorUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.email() != null && changes.email().isPresent()) values.put("email", changes.email().value());
        return values;
    }

    /** Stores a new Author after checking it. */
    public AuthorRead createAuthor(AuthorCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.email() != null) values.put("email", data.email());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Author entity = new Author();
            apply(entity, values);
            return read(uow.authors().insert(entity));
        });
    }

    /** The Author with this key; NotFoundException when there is none. */
    public AuthorRead getAuthor(String id) {
        return read(find(uow, id));
    }

    /** A page of authors, by primary key. */
    public Page<AuthorRead> listAuthors(int offset, int limit) {
        return uow.authors().list(offset, limit).map(AuthorService::read);
    }

    /** Changes the given values of a Author. */
    public AuthorRead updateAuthor(String id, AuthorUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Author current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.authors().update(current));
        });
    }

    /** Deletes a Author. */
    public void deleteAuthor(String id) {
        uow.transaction((uow) -> {
            Author current = find(uow, id);
            if (!uow.posts().listByAuthor(current.getId()).isEmpty()) throw new ConflictException("Author", "rows of posts still point to it", List.of("posts"));
            uow.authors().delete(current);
            return null;
        });
    }
}

