        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.title() != null && changes.title().isPresent()) values.put("title", changes.title().value());
        if (changes.author() != null && changes.author().isPresent()) values.put("author", changes.author().value());
        if (changes.publishedAt() != null && changes.publishedAt().isPresent()) values.put("publishedAt", changes.publishedAt().value());
        if (changes.comments() != null && changes.comments().isPresent()) values.put("comments", changes.comments().value());
        return values;
    }

    /** What a Comment does not follow of its rules, each with the path of its field. */
    private static void checkComment(Post.Comment value, String path, List<FieldError> errors) {
        if (value.getText() == null) errors.add(new FieldError(path + ".text", "is required"));
        if (value.getMarks() == null) errors.add(new FieldError(path + ".marks", "is required"));
    }

    /** Stores a new Post after checking it. */
    public PostRead createPost(PostCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.title() != null) values.put("title", data.title());
        if (data.author() != null) values.put("author", data.author());
        if (data.publishedAt() != null) values.put("publishedAt", data.publishedAt());
        if (data.comments() != null) values.put("comments", data.comments());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Post entity = new Post();
            apply(entity, values);
            return read(uow.posts().insert(entity));
        });
    }

    /** The Post with this key; NotFoundException when there is none. */
    public PostRead getPost(String id) {
        return read(find(uow, id));
    }

    /** A page of posts, by primary key. */
    public Page<PostRead> listPosts(int offset, int limit) {
        return uow.posts().list(offset, limit).map(PostService::read);
    }

    /** Changes the given values of a Post. */
    public PostRead updatePost(String id, PostUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Post current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.posts().update(current));
        });
    }

    /** Deletes a Post. */
    public void deletePost(String id) {
        uow.transaction((uow) -> {
            Post current = find(uow, id);
            uow.posts().delete(current);
            return null;
        });
    }

    /** The posts with this author. */
    public List<PostRead> listPostsByAuthor(String author) {
        return uow.posts().listByAuthor(author).stream().map(PostService::read).toList();
    }

    /** Adds an item to comments. */
    public PostRead addComment(String id, Post.Comment comment) {
        List<FieldError> errors = new ArrayList<>();
        checkComment(comment, "comments", errors);
        if (!errors.isEmpty()) throw new ValidationFailedException("Post", errors);
        return uow.transaction((uow) -> {
            find(uow, id);
            return read(uow.posts().addComment(id, comment).orElseThrow(() -> new NotFoundException("Post", id)));
        });
    }

    /** Removes an item from comments, by its identifier. */
    public PostRead removeComment(String id, String commentId) {
        return uow.transaction((uow) -> {
            Post current = find(uow, id);
            if (current.getComments() == null || current.getComments().stream().noneMatch((item) -> commentId.equals(item.getId()))) throw new NotFoundException("Comment", commentId);
            return read(uow.posts().removeComment(id, commentId).orElseThrow(() -> new NotFoundException("Post", id)));
        });
    }
}

